//go:build live

// trae_live_refresh_test.go — credential-driven end-to-end verification of
// the v0.8.65 renewal chain on a REAL pre-0.12.73 credential (no device keys):
//
//	leg 1 (refresh): Client.RefreshToken must mint a fresh Cloud-IDE-JWT via
//	         the bound-exchange ladder (SOLO_PC identity first, keys
//	         self-generated by ensureDeviceKeyLocked) — the exact path issue
//	#38/#33 reported as broken before v0.12.74.
//	leg 2 (chat):   ChatStream on the renewed token must answer (llm_utils_chat
//	         200 + non-empty content) — proves the renewed JWT is actually
//	         usable, not just minted.
//
// Run:
//
//	TRAE_CRED=/path/to/cred.json [TRAE_MODEL=glm-5.3-flash] \
//	  go test -tags live -run TestLiveRefreshAndChat -v ./plugins/trae
//
// Skipped unless -tags live AND TRAE_CRED are set, so normal CI stays hermetic.
package main

import (
	"encoding/json"
	"fmt"
	"os"
	"strings"
	"testing"
	"time"

	"github.com/mmqz/cpa-multi-plugins/plugins/trae/auth"
	"github.com/mmqz/cpa-multi-plugins/plugins/trae/upstream"
)

func liveTraeAuth(t *testing.T) *auth.Auth {
	t.Helper()
	path := strings.TrimSpace(os.Getenv("TRAE_CRED"))
	if path == "" {
		t.Skip("TRAE_CRED not set — live refresh verification skipped")
	}
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read cred: %v", err)
	}
	a, err := auth.Parse(raw)
	if err != nil {
		t.Fatalf("parse cred: %v", err)
	}
	if a.Variant == "" {
		a.Variant = "cn"
	}
	t.Logf("cred loaded: uid=%s variant=%s expiresAt=%s (expired=%v)",
		a.UID, a.Variant, time.Unix(a.ExpiresAt, 0).Format(time.RFC3339),
		time.Now().Unix() > a.ExpiresAt)
	return a
}

func TestLiveRefreshAndChat(t *testing.T) {
	a := liveTraeAuth(t)
	c := upstream.New()

	oldToken := a.AccessToken
	oldExpiry := a.ExpiresAt

	// ---- leg 1: refresh (bound exchange ladder, legacy credential) ----
	if err := c.RefreshToken(a); err != nil {
		t.Fatalf("refresh failed: %v", err)
	}
	if a.AccessToken == "" || a.AccessToken == oldToken {
		t.Fatalf("refresh did not mint a new token (changed=%v)", a.AccessToken != oldToken)
	}
	if a.ExpiresAt <= time.Now().Unix() {
		t.Errorf("refresh left expiry in the past: %d", a.ExpiresAt)
	}
	t.Logf("refresh OK: expiresAt %s -> %s, refreshToken changed=%v",
		time.Unix(oldExpiry, 0).Format(time.RFC3339),
		time.Unix(a.ExpiresAt, 0).Format(time.RFC3339),
		a.RefreshToken != "")

	// Persist the renewed pair so follow-up runs (and the report) use it.
	if path := strings.TrimSpace(os.Getenv("TRAE_CRED")); path != "" {
		doc := map[string]any{
			"provider": "trae", "type": "trae",
			"account": map[string]any{"uid": a.UID, "nickname": a.Nickname, "enterpriseId": a.EnterpriseID},
			"auth": map[string]any{
				"accessToken": a.AccessToken, "refreshToken": a.RefreshToken,
				"expiresAt": a.ExpiresAt, "domain": a.Domain, "apiHost": a.APIHost,
				"machineId": a.MachineID, "deviceId": a.DeviceID,
				"variant":         a.Variant,
				"devicePublicKey": a.DevicePublicKey, "devicePrivateKey": a.DevicePrivateKey,
			},
		}
		if raw, err := json.MarshalIndent(doc, "", " "); err == nil {
			_ = os.WriteFile(path, raw, 0o600)
		}
	}

	// ---- leg 2: chat round-trip on the renewed token ----
	model := strings.TrimSpace(os.Getenv("TRAE_MODEL"))
	if model == "" {
		model = "glm-5.3-flash"
	}
	body, _ := json.Marshal(map[string]any{
		"model":    model,
		"stream":   true,
		"messages": []map[string]any{{"role": "user", "content": "请只回复两个字：成功"}},
	})
	rc, status, respBody, err := c.ChatStream(a, body, model)
	if err != nil {
		t.Fatalf("chat transport: %v", err)
	}
	if status >= 400 {
		t.Fatalf("chat http %d: %s", status, liveTruncate(string(respBody), 300))
	}
	defer rc.Close()

	agg, err := upstream.Aggregate(rc)
	if err != nil {
		t.Fatalf("chat aggregate: %v", err)
	}
	content := ""
	if choices, ok := agg["choices"].([]any); ok && len(choices) > 0 {
		if ch, ok := choices[0].(map[string]any); ok {
			if msg, ok := ch["message"].(map[string]any); ok {
				content, _ = msg["content"].(string)
			}
		}
	}
	finish := ""
	if choices, ok := agg["choices"].([]any); ok && len(choices) > 0 {
		if ch, ok := choices[0].(map[string]any); ok {
			finish, _ = ch["finish_reason"].(string)
		}
	}
	t.Logf("chat OK: model=%s finish=%s content=%q", model, finish, liveTruncate(content, 120))
	if strings.TrimSpace(content) == "" {
		t.Errorf("chat returned empty content (agg=%s)", liveTruncate(fmt.Sprint(agg), 300))
	}
}

func liveTruncate(s string, n int) string {
	if len(s) <= n {
		return s
	}
	return s[:n] + "..."
}

var _ = fmt.Sprint
